/**
 * Pure types of the curated export: the redaction rule a deployment configures,
 * the `curation` block every exported record carries, the export manifest left
 * beside the lines, and the request and report of one curated export.
 *
 * @module @deepseek-ai/dsh-curator/types
 */

import type { DataUsePurpose } from '@deepseek-ai/dsh-data-use/types'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import type {
  Trajectory,
  TrajectoryExportSkip,
  TrajectoryFormat,
  TrajectorySink,
} from '@deepseek-ai/dsh-trajectories/types'

/** One configured redaction rule, as `cordis.yml` states it. */
export interface RedactionRule {
  /** Non-empty identity, unique inside its profile; the key hit counts are reported under. */
  readonly id: string
  /** JavaScript regular expression source, compiled at load. */
  readonly pattern: string
  /** Regular expression flags; the global flag is added whether or not it is listed, and the sticky flag is refused. */
  readonly flags?: string
  /** Literal text every match becomes; `$`-sequences are written verbatim, never expanded. */
  readonly replacement: string
}

/** One configured profile: the rules an export applies, in the order they run. */
export interface RedactionProfileConfig {
  /** Whether the rule set this package ships runs ahead of `rules`. */
  readonly shipped: boolean
  /** Deployment-owned rules, applied after the shipped ones. */
  readonly rules?: readonly RedactionRule[]
}

/** What the curator recorded about one exported record. */
export interface TrajectoryRedaction {
  /** Profile id the export ran under. */
  readonly profile: string
  /** Lowercase SHA-256 hex over the profile's effective rules in order. */
  readonly profileSha256: string
  /** Replacements this record received, per rule id; a rule that matched nothing is absent. */
  readonly hits: Readonly<Record<string, number>>
}

/** The block the curator adds to every record it exports. */
export interface TrajectoryCuration {
  /** Always `true`: a record without a `curation` block was written by the unredacted exporter. */
  readonly redactionApplied: true
  /** The profile that ran and what it replaced in this record. */
  readonly redaction: TrajectoryRedaction
  /** Region the session's pinned terms name, so a sink can partition by it without reading the logs again. */
  readonly residency: string
}

/** One exported line: the trajectory record plus the curator's own block. */
export type CuratedTrajectory = Trajectory & {
  readonly curation: TrajectoryCuration
}

/** Sessions one export did not write, by the reason each was withheld. */
export interface ExportWithheld {
  /** Withheld because their environment is held out. */
  readonly heldOut: number
  /** Withheld because their stamp's district is not one this export writes. */
  readonly districts: number
  /** Withheld because their pinned terms do not admit the export's purpose, or because they carry none. */
  readonly terms: number
}

/** The durable record of one curated export, written beside its lines. */
export interface ExportManifest {
  /** Manifest format tag. */
  readonly version: string
  /** Epoch milliseconds the export finished at. */
  readonly exportedAt: number
  /** Purpose the export serves, which every written session's terms admit. */
  readonly purpose: DataUsePurpose
  /** Profile id the export ran under. */
  readonly profile: string
  /** Lowercase SHA-256 hex over that profile's effective rules in order. */
  readonly profileSha256: string
  /** Lines written. */
  readonly records: number
  /** Sessions withheld, by reason. */
  readonly withheld: ExportWithheld
  /** Replacements over the whole export, per rule id; every rule of the profile is listed, including those that matched nothing. */
  readonly ruleHits: Readonly<Record<string, number>>
  /** Lowercase SHA-256 hex over the written lines in order, which is the digest of the sink's bytes. */
  readonly recordsSha256: string
  /** Record format of every written line. */
  readonly trajectoryFormat: TrajectoryFormat
}

/** What to export, under which terms, and where. */
export interface CuratedExportRequest {
  /** Purpose the export serves; a session whose terms do not list it is withheld. */
  readonly purpose: DataUsePurpose
  /** Profile to apply; absent uses the configured `defaultProfile`, and an export with neither is refused. */
  readonly profile?: string
  /** Sessions to consider; absent considers every persisted session. */
  readonly sessions?: readonly SessionId[]
  /** Destination of the curated lines; closed exactly once by the wrapped exporter. */
  readonly sink: TrajectorySink
  /** Where the manifest is written; absent returns it in the report only. */
  readonly manifestPath?: string
  /** Write only trajectories whose reward outcome is `1`. */
  readonly rewardedOnly?: boolean
  /** Also write sessions whose environment is held out. */
  readonly includeHeldOut?: boolean
  /** Districts to export; absent applies the exporter's configured `withheldDistricts`. */
  readonly districts?: readonly string[]
}

/** Counts of one curated export, beside the manifest it wrote. */
export interface CuratedExportReport {
  /** The manifest, whether or not `manifestPath` asked for it on disk. */
  readonly manifest: ExportManifest
  /** Sessions the request named or the store listed. */
  readonly sessions: number
  /** Lines written. */
  readonly exported: number
  /** Written lines whose reward outcome is `1`. */
  readonly rewarded: number
  /** Admitted sessions withheld by `rewardedOnly`. */
  readonly filtered: number
  /** Admitted sessions withheld because their environment is held out. */
  readonly heldOut: number
  /** Admitted sessions withheld because their stamp's district is not one this export writes. */
  readonly withheldByDistrict: number
  /** Sessions withheld because their pinned terms do not admit the purpose, or because they carry none. */
  readonly withheldByTerms: number
  /** Sessions that could not be read, either while reading their terms or while folding them. */
  readonly skipped: readonly TrajectoryExportSkip[]
}

/**
 * Redaction profiles and the walk that applies one to a trajectory record: the
 * rule set this package ships, the load-time compilation every configured rule
 * passes, and the enumeration of what a record never has redacted.
 * @module @deepseek-ai/dsh-curator
 */

import { createHash } from 'node:crypto'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import type { Trajectory } from '@deepseek-ai/dsh-trajectories/types'
import type { RedactionProfileConfig, RedactionRule } from './types.ts'

/** Stable error codes of a refused profile or a refused export. */
export type CuratorErrorCode =
  | 'CURATOR_INVALID_CONFIG'
  | 'CURATOR_PROFILE_REQUIRED'
  | 'CURATOR_PROFILE_UNKNOWN'
  | 'CURATOR_UNADMITTED_RECORD'

/** Error raised by a profile the curator cannot compile or an export it refuses to run. */
export class CuratorError extends HarnessError {
  /**
   * @param message - human-readable reason, naming the profile or rule at fault.
   * @param code - stable machine-routable classification.
   */
  // Keep the constructor to narrow HarnessError's string code at this boundary.
  // oxlint-disable-next-line typescript/no-useless-constructor -- type-only narrowing
  constructor(message: string, code: CuratorErrorCode) {
    super(message, code)
  }
}

/**
 * The rules this package owns, applied ahead of a profile's own when it sets
 * `shipped: true`. Each covers one credential or identifier format that turns
 * up verbatim in agent transcripts; none of them claims to be exhaustive, and a
 * deployment adds its own formats through `rules`.
 */
export const SHIPPED_REDACTION_RULES: readonly RedactionRule[] = [
  {
    id: 'shipped:email',
    pattern: String.raw`[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}`,
    flags: 'g',
    replacement: '[redacted:email]',
  },
  {
    id: 'shipped:bearer-token',
    // Twenty characters keeps the prose "Bearer token" out of the rule while
    // matching every credential an Authorization header actually carries.
    pattern: String.raw`\bBearer\s+[A-Za-z0-9._~+/-]{20,}=*`,
    flags: 'gi',
    replacement: 'Bearer [redacted:token]',
  },
  {
    id: 'shipped:api-key',
    pattern: String.raw`\bsk-[A-Za-z0-9_-]{4,}\b`,
    flags: 'g',
    replacement: '[redacted:api-key]',
  },
  {
    id: 'shipped:ipv4',
    pattern: String.raw`\b(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\b`,
    flags: 'g',
    replacement: '[redacted:ipv4]',
  },
  {
    id: 'shipped:e164-phone',
    pattern: String.raw`\+[1-9]\d{7,14}\b`,
    flags: 'g',
    replacement: '[redacted:phone]',
  },
]

/**
 * Record subtrees that carry only identifiers, digests, and counts. Nothing
 * under `environment` (the `environment/run` stamp), `steps`, `parity`, or
 * `provenance` is free text, and redacting one of them would break the keys a
 * scoreboard and a decontamination check are computed from.
 */
const NEVER_REDACTED_SUBTREES: ReadonlySet<string> = new Set(['environment', 'steps', 'parity', 'provenance'])

/**
 * Key names that hold an identifier or a closed vocabulary wherever they appear
 * in the record. A rule that rewrote one of these would corrupt a value the
 * record's readers switch on rather than protect anything the record carries.
 */
const NEVER_REDACTED_KEYS: ReadonlySet<string> = new Set([
  'format',
  'type',
  'id',
  'sessionId',
  'parentSession',
  'agentPreset',
  'role',
  'sourceKind',
  'toolCallId',
  'basis',
  'phase',
  'goalId',
  'checkId',
  'status',
  'isolation',
  'executor',
  'provider',
  'model',
  'reasoningEffort',
  'attachmentId',
  'mediaType',
])

/**
 * Paths whose `name` is a registered tool name rather than free text. The key
 * alone cannot decide it: an attachment's `name` is a display filename and is
 * redacted like any other text a person supplied.
 */
const NEVER_REDACTED_PATHS: ReadonlySet<string> = new Set([
  'tools.name',
  'messages.content.name',
  'messages.toolCalls.name',
])

/** Where one string sits in the record; array indices are elided, so every element of a list shares its path. */
interface RedactionSite {
  /** Top-level record key the string descends from. */
  readonly root: string
  /** Dotted path from the record root, indices elided. */
  readonly path: string
  /** Key the string is stored under. */
  readonly key: string
}

/** One rule ready to run, with the regular expression the load compiled. */
export interface CompiledRedactionRule {
  /** The configured rule id, which hit counts are reported under. */
  readonly id: string
  /** The compiled pattern, always global so every hit is replaced and counted. */
  readonly regex: RegExp
  /** Literal replacement text. */
  readonly replacement: string
}

/** A profile as the service holds it: its rules in run order and the digest that addresses them. */
export interface RedactionProfile {
  /** Configured profile id. */
  readonly id: string
  /** Shipped rules first when the profile asked for them, then the configured ones. */
  readonly rules: readonly CompiledRedactionRule[]
  /** Lowercase SHA-256 hex over the rules' sources, flags, and replacements in order. */
  readonly sha256: string
}

/**
 * Compile one configured profile, refusing every rule a load may not accept.
 * @param id - the profile id, named in every rejection.
 * @param config - the profile's shipped-rule choice and its own rules.
 * @returns the compiled profile with its digest.
 * @throws {@link CuratorError} `CURATOR_INVALID_CONFIG` when the profile holds
 *   no rule, or when a rule has an empty id, an id another rule in the same
 *   profile already used, the sticky flag, or a pattern that does not compile.
 */
export function compileProfile(id: string, config: RedactionProfileConfig): RedactionProfile {
  const rules = [...config.shipped ? SHIPPED_REDACTION_RULES : [], ...config.rules ?? []]
  if (rules.length === 0) {
    throw new CuratorError(
      `redaction profile "${id}" lists no rule and does not take the shipped set, so it would redact nothing`,
      'CURATOR_INVALID_CONFIG',
    )
  }
  const seen = new Set<string>()
  const compiled = rules.map((rule) => {
    if (rule.id.length === 0) throw new CuratorError(`redaction profile "${id}" has a rule with an empty id`, 'CURATOR_INVALID_CONFIG')
    if (seen.has(rule.id)) {
      throw new CuratorError(`redaction profile "${id}" lists rule "${rule.id}" twice, so its hit count would name two rules`, 'CURATOR_INVALID_CONFIG')
    }
    seen.add(rule.id)
    return { id: rule.id, regex: compileRule(id, rule), replacement: rule.replacement }
  })
  return { id, rules: compiled, sha256: profileDigest(compiled) }
}

/**
 * Compile one rule's pattern, always globally.
 * @param profileId - owning profile, named in a rejection.
 * @param rule - the configured rule.
 * @returns the compiled expression.
 * @throws {@link CuratorError} on the sticky flag or an uncompilable pattern.
 */
function compileRule(profileId: string, rule: RedactionRule): RegExp {
  const flags = rule.flags ?? ''
  if (flags.includes('y')) {
    throw new CuratorError(
      `redaction rule "${rule.id}" of profile "${profileId}" sets the sticky flag, which would match only at the expression's last index and leave later hits in the record`,
      'CURATOR_INVALID_CONFIG',
    )
  }
  try {
    return new RegExp(rule.pattern, flags.includes('g') ? flags : `${flags}g`)
  } catch (error: unknown) {
    const reason = error instanceof Error ? error.message : String(error)
    throw new CuratorError(`redaction rule "${rule.id}" of profile "${profileId}" does not compile: ${reason}`, 'CURATOR_INVALID_CONFIG')
  }
}

/**
 * Digest the rules that will actually run, so a manifest states which rules a
 * profile name stood for rather than only the name.
 * @param rules - the compiled rules in run order.
 * @returns lowercase SHA-256 hex over their canonical encoding.
 */
function profileDigest(rules: readonly CompiledRedactionRule[]): string {
  const canonical = rules.map(rule => ({
    id: rule.id,
    source: rule.regex.source,
    flags: rule.regex.flags,
    replacement: rule.replacement,
  }))
  return createHash('sha256').update(JSON.stringify(canonical)).digest('hex')
}

/**
 * Replace every match of every rule, in rule order, counting the replacements.
 * The replacement is returned from a function, so a `$&` or `$1` a deployment
 * configured is written literally and can never splice the matched text back in.
 * @param text - the string to redact.
 * @param rules - the profile's rules in run order.
 * @param hits - replacement counts per rule id, incremented in place.
 * @returns the redacted string.
 */
export function applyRules(text: string, rules: readonly CompiledRedactionRule[], hits: Map<string, number>): string {
  let redacted = text
  for (const rule of rules) {
    redacted = redacted.replace(rule.regex, () => {
      hits.set(rule.id, (hits.get(rule.id) ?? 0) + 1)
      return rule.replacement
    })
  }
  return redacted
}

/**
 * Whether one string keeps its exact value.
 * @param site - where the string sits in the record.
 * @returns true for the record's identifiers, discriminants, and tool names.
 */
function keeps(site: RedactionSite): boolean {
  return NEVER_REDACTED_SUBTREES.has(site.root)
    || NEVER_REDACTED_KEYS.has(site.key)
    || NEVER_REDACTED_PATHS.has(site.path)
}

/**
 * Redact one value and everything under it.
 * @param value - the value at `site`.
 * @param site - where the value sits in the record.
 * @param rules - the profile's rules in run order.
 * @param hits - replacement counts per rule id, incremented in place.
 * @returns the value with every redacted string replaced.
 */
function redactValue(value: unknown, site: RedactionSite, rules: readonly CompiledRedactionRule[], hits: Map<string, number>): unknown {
  if (typeof value === 'string') return keeps(site) ? value : applyRules(value, rules, hits)
  if (Array.isArray(value)) return value.map(item => redactValue(item, site, rules, hits))
  if (typeof value === 'object' && value !== null) return redactEntries(value, site, rules, hits)
  return value
}

/**
 * Redact every property of one object, descending with the property's path.
 * @param value - the object to walk.
 * @param site - where the object sits, or `undefined` at the record root.
 * @param rules - the profile's rules in run order.
 * @param hits - replacement counts per rule id, incremented in place.
 * @returns a new object with the same keys.
 */
function redactEntries(
  value: object,
  site: RedactionSite | undefined,
  rules: readonly CompiledRedactionRule[],
  hits: Map<string, number>,
): Record<string, unknown> {
  return Object.fromEntries(Object.entries(value).map(([key, entry]) => [
    key,
    redactValue(entry, site === undefined ? { root: key, path: key, key } : { root: site.root, path: `${site.path}.${key}`, key }, rules, hits),
  ]))
}

/**
 * Apply a profile to one trajectory record. Every string is redacted except the
 * record's identifiers, its readers' discriminants, and registered tool names,
 * so a field added to the record format is redacted until someone decides
 * otherwise rather than exported until someone notices.
 * @param record - the folded record, as the exporter serialized it.
 * @param rules - the profile's rules in run order.
 * @param hits - replacement counts per rule id, incremented in place.
 * @returns a new record with the same keys and every redacted string replaced.
 */
export function redactTrajectory(record: Trajectory, rules: readonly CompiledRedactionRule[], hits: Map<string, number>): Trajectory {
  // The walk replaces string leaves and preserves every key, so the result is
  // the same record format with redacted text.
  return redactEntries(record, undefined, rules, hits) as unknown as Trajectory
}

/**
 * Curated export: the trajectory exporter wrapped in the two rules a transcript
 * may not leave the lab without. It refuses to run without a redaction profile,
 * withholds every session whose pinned `dataUse/terms` do not admit the
 * export's purpose, redacts the record before it reaches the sink, and writes
 * one {@link ExportManifest} beside the lines. It reads persisted logs and
 * writes no session event. The
 * [curator Agent Note](../../../.agents/notes/proposed/architecture/2026-09-06-curator.md)
 * owns the design rationale.
 * @module @deepseek-ai/dsh-curator
 */

import { createHash } from 'node:crypto'
import { writeFile } from 'node:fs/promises'
import { Context, Service } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import { termsOf } from '@deepseek-ai/dsh-data-use'
import type { DataUseTerms } from '@deepseek-ai/dsh-data-use'
// Type-only: resolves ctx.dataUse.
import type {} from '@deepseek-ai/dsh-data-use'
// Type-only: resolves ctx.sessionPersistence.
import type {} from '@deepseek-ai/dsh-session-persistence'
import type { SessionId } from '@deepseek-ai/dsh-session/types'
import { TRAJECTORY_FORMAT } from '@deepseek-ai/dsh-trajectories'
// Type-only: resolves ctx.trajectories.
import type {} from '@deepseek-ai/dsh-trajectories'
import type { Trajectory, TrajectoryExportSkip } from '@deepseek-ai/dsh-trajectories/types'
import { compileProfile, CuratorError, redactTrajectory } from './redaction.ts'
import type { RedactionProfile } from './redaction.ts'
import type {
  CuratedExportReport,
  CuratedExportRequest,
  CuratedTrajectory,
  ExportManifest,
  RedactionProfileConfig,
} from './types.ts'

export type * from './types.ts'
export {
  applyRules,
  CuratorError,
  redactTrajectory,
  SHIPPED_REDACTION_RULES,
  compileProfile,
  type CompiledRedactionRule,
  type CuratorErrorCode,
  type RedactionProfile,
} from './redaction.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    curator: CuratorService
  }
}

/** Format tag every {@link ExportManifest} carries. */
export const EXPORT_MANIFEST_VERSION = 'dsh-export-manifest/1'

/** Deployment choices of the curated export, validated from `cordis.yml`. */
export interface Config {
  /**
   * Redaction profiles by id, at least one. Redaction is not optional: there is
   * no configuration under which a curated export runs without a profile, so a
   * deployment states here which profiles it can export under.
   */
  profiles: Record<string, RedactionProfileConfig>
  /** Profile an export that names none applies; an export with neither is refused. */
  defaultProfile?: string
}

/** Curated export (`ctx.curator`): redacted, terms-gated trajectory export with a manifest. */
export class CuratorService extends Service {
  static inject = ['trajectories', 'sessionPersistence', 'dataUse']

  // Inline schema call: the config catalog walks `static Config` statically.
  static Config: z<Config> = z.object({
    profiles: z.dict(z.object({
      shipped: z.boolean().required(),
      rules: z.array(z.object({
        id: z.string().required(),
        pattern: z.string().required(),
        flags: z.string(),
        replacement: z.string().required(),
      })).default([]),
    })).required(),
    defaultProfile: z.string(),
  })

  private readonly profiles: Map<string, RedactionProfile>
  private readonly defaultProfile: string | undefined

  constructor(ctx: Context, config: Config) {
    super(ctx, 'curator')
    const entries = Object.entries(config.profiles)
    if (entries.length === 0) {
      throw new CuratorError('profiles is empty, so this deployment could export under no profile at all', 'CURATOR_INVALID_CONFIG')
    }
    this.profiles = new Map(entries.map(([id, profile]) => [id, compileProfile(id, profile)]))
    if (config.defaultProfile !== undefined && !this.profiles.has(config.defaultProfile)) {
      throw new CuratorError(
        `defaultProfile "${config.defaultProfile}" is not one of the configured profiles ${[...this.profiles.keys()].join(', ')}`,
        'CURATOR_INVALID_CONFIG',
      )
    }
    this.defaultProfile = config.defaultProfile
  }

  /**
   * Export the sessions whose pinned terms admit the purpose, redacted under
   * one profile, and write the manifest that accounts for every session the
   * request considered.
   * @param request - the purpose, the profile, the sessions, the sink, and the exporter's own filters.
   * @returns the manifest with the counts behind it, including the sessions withheld by terms and the ones that could not be read.
   * @throws {@link CuratorError} `CURATOR_PROFILE_REQUIRED` when neither the
   *   request nor the configuration names a profile, and `CURATOR_PROFILE_UNKNOWN`
   *   when the request names one this deployment did not configure. Nothing is
   *   written and the sink is not touched in either case.
   */
  async export(request: CuratedExportRequest): Promise<CuratedExportReport> {
    const profile = this.resolveProfile(request.profile)
    const skipped: TrajectoryExportSkip[] = []
    const admitted = new Map<SessionId, DataUseTerms>()
    let withheldByTerms = 0
    const candidates = request.sessions ?? (await this.ctx.sessionPersistence.list()).map(header => header.id)
    for (const sessionId of candidates) {
      let terms: DataUseTerms | undefined
      try {
        terms = termsOf((await this.ctx.sessionPersistence.inspect(sessionId)).events)
      } catch (error: unknown) {
        skipped.push({ sessionId, reason: error instanceof Error ? error.message : String(error) })
        continue
      }
      // No terms, no export: an unpinned transcript states no purpose, and a
      // purpose nobody recorded is never assumed.
      if (terms === undefined || !terms.purposes.includes(request.purpose)) {
        withheldByTerms += 1
        continue
      }
      admitted.set(sessionId, terms)
    }

    const ruleHits = new Map(profile.rules.map(rule => [rule.id, 0] as const))
    const records = createHash('sha256')
    const report = await this.ctx.trajectories.export({
      sessions: [...admitted.keys()],
      sink: {
        write: async (line) => {
          const curated = this.curate(JSON.parse(line) as Trajectory, profile, admitted, ruleHits)
          records.update(curated)
          await request.sink.write(curated)
        },
        close: () => request.sink.close(),
      },
      ...request.rewardedOnly === undefined ? {} : { rewardedOnly: request.rewardedOnly },
      ...request.includeHeldOut === undefined ? {} : { includeHeldOut: request.includeHeldOut },
      ...request.districts === undefined ? {} : { districts: request.districts },
    })

    const manifest: ExportManifest = {
      version: EXPORT_MANIFEST_VERSION,
      exportedAt: Date.now(),
      purpose: request.purpose,
      profile: profile.id,
      profileSha256: profile.sha256,
      records: report.exported,
      withheld: { heldOut: report.heldOut, districts: report.withheld, terms: withheldByTerms },
      ruleHits: Object.fromEntries(ruleHits),
      recordsSha256: records.digest('hex'),
      trajectoryFormat: TRAJECTORY_FORMAT,
    }
    if (request.manifestPath !== undefined) await writeFile(request.manifestPath, `${JSON.stringify(manifest, undefined, 2)}\n`)
    return {
      manifest,
      sessions: candidates.length,
      exported: report.exported,
      rewarded: report.rewarded,
      filtered: report.filtered,
      heldOut: report.heldOut,
      withheldByDistrict: report.withheld,
      withheldByTerms,
      skipped: [...skipped, ...report.skipped],
    }
  }

  /**
   * The profile one export runs under.
   * @param requested - the profile the request named, if any.
   * @returns the compiled profile.
   * @throws {@link CuratorError} when no profile is named or the named one is unknown.
   */
  private resolveProfile(requested: string | undefined): RedactionProfile {
    const id = requested ?? this.defaultProfile
    if (id === undefined) {
      throw new CuratorError(
        'this export names no redaction profile and no defaultProfile is configured; a curated export never runs unredacted',
        'CURATOR_PROFILE_REQUIRED',
      )
    }
    const profile = this.profiles.get(id)
    if (profile === undefined) {
      throw new CuratorError(
        `redaction profile "${id}" is not configured; this deployment configured ${[...this.profiles.keys()].join(', ')}`,
        'CURATOR_PROFILE_UNKNOWN',
      )
    }
    return profile
  }

  /**
   * Redact one folded record and attach the curation block the export states.
   * @param record - the record the exporter serialized.
   * @param profile - the profile this export runs under.
   * @param admitted - the terms of every session the terms pass admitted.
   * @param ruleHits - export-wide replacement counts, incremented in place.
   * @returns the curated line, newline included.
   * @throws {@link CuratorError} when the record names a session the terms pass did not admit.
   */
  private curate(
    record: Trajectory,
    profile: RedactionProfile,
    admitted: ReadonlyMap<SessionId, DataUseTerms>,
    ruleHits: Map<string, number>,
  ): string {
    const terms = admitted.get(record.id)
    /* v8 ignore next 4 -- the exporter reads only the sessions the terms pass admitted and mapped. */
    if (terms === undefined) {
      throw new CuratorError(
        `session ${record.id} reached the sink without admitted terms`,
        'CURATOR_UNADMITTED_RECORD',
      )
    }
    const hits = new Map<string, number>()
    const redacted = redactTrajectory(record, profile.rules, hits)
    for (const [id, count] of hits) ruleHits.set(id, (ruleHits.get(id) ?? 0) + count)
    const curated: CuratedTrajectory = {
      ...redacted,
      curation: {
        redactionApplied: true,
        redaction: { profile: profile.id, profileSha256: profile.sha256, hits: Object.fromEntries(hits) },
        residency: terms.residency,
      },
    }
    return `${JSON.stringify(curated)}\n`
  }
}

export default CuratorService

